basicCode.vanilla:
import { createComposer } from '@/components/ui/composer';

const composer = createComposer({
  labels,
  onSubmit: (texto) => enviar(texto),
});

withRunningCode.vanilla:
// O estado de geração é de quem consome: o composer não sabe se a
// resposta chegou.
composer.setRunning(true);
composer.addEventListener('nds-stop', () => cancelar());

withRunningCode.react:
// O estado de geração é de quem consome: o composer não sabe se a
// resposta chegou.
<Composer labels={labels} running={gerando} onSubmit={enviar} onStop={cancelar} />

extensibilityCode.vanilla:
// O trilho é um ESPAÇO. Quem consome põe o que quiser nele.
createComposer({
  labels,
  railStart: [
    createButton({ label: 'Anexar', variant: 'ghost', size: 'sm' }),
  ],
});

extensibilityCode.react:
// O trilho é um ESPAÇO. Quem consome põe o que quiser nele.
<Composer
  labels={labels}
  railStart={<Button variant="ghost" size="sm">Anexar</Button>}
/>

customizationCode.web:
.nds-composer-field {
  border-radius: var(--radius-lg);
}

/* A moldura é do conjunto: o anel acende no formulário inteiro, e não
   só em volta do texto. */
.nds-composer-field:focus-within {
  box-shadow: 0 0 0 3px hsl(var(--ring) / 0.3);
}

